/**
 * contrastCheck.ts — minimal WCAG contrast ratio utilities.
 *
 * Used by MentionPill and PostCard avatar ring to fall back to cog-border
 * when a faction color fails WCAG AA contrast (4.5:1 for normal text,
 * 3:1 for large text / UI components per WCAG 2.2 §1.4.11).
 *
 * The palette is constrained to 8 pre-checked colors so this utility is
 * defense-in-depth — it should never fail for palette colors against
 * standard light/dark surfaces.
 */

/**
 * Convert a hex color string to linear sRGB [0, 1] values.
 * Accepts 3-char (#RGB) and 6-char (#RRGGBB) formats.
 * Returns null on parse failure.
 */
function hexToLinearRgb(
  hex: string,
): { r: number; g: number; b: number } | null {
  const clean = hex.replace("#", "");
  let r: number;
  let g: number;
  let b: number;

  if (clean.length === 3) {
    r = parseInt(clean[0] + clean[0], 16);
    g = parseInt(clean[1] + clean[1], 16);
    b = parseInt(clean[2] + clean[2], 16);
  } else if (clean.length === 6) {
    r = parseInt(clean.slice(0, 2), 16);
    g = parseInt(clean.slice(2, 4), 16);
    b = parseInt(clean.slice(4, 6), 16);
  } else {
    return null;
  }

  if (isNaN(r) || isNaN(g) || isNaN(b)) return null;

  function linearize(v: number): number {
    const c = v / 255;
    return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  }

  return {
    r: linearize(r),
    g: linearize(g),
    b: linearize(b),
  };
}

/**
 * Compute the relative luminance of a hex color per WCAG 2.2.
 * Returns null if the hex is unparseable.
 */
export function relativeLuminance(hex: string): number | null {
  const rgb = hexToLinearRgb(hex);
  if (rgb === null) return null;
  return 0.2126 * rgb.r + 0.7152 * rgb.g + 0.0722 * rgb.b;
}

/**
 * Compute the contrast ratio between two hex colors.
 * Returns null if either color is unparseable.
 */
export function contrastRatio(fg: string, bg: string): number | null {
  const L1 = relativeLuminance(fg);
  const L2 = relativeLuminance(bg);
  if (L1 === null || L2 === null) return null;
  const lighter = Math.max(L1, L2);
  const darker = Math.min(L1, L2);
  return (lighter + 0.05) / (darker + 0.05);
}

/**
 * Returns true if the fg/bg pair meets WCAG 2.2 AA for UI components
 * (contrast ratio ≥ 3:1 per §1.4.11 Non-text Contrast).
 *
 * For decorative uses (avatar ring, accent bar) we use 3:1 since these
 * are non-text visual indicators, not body text (which requires 4.5:1).
 */
export function isWcagAA(fg: string, bg: string): boolean {
  const ratio = contrastRatio(fg, bg);
  if (ratio === null) return false;
  return ratio >= 3.0;
}


