// design-ratchet-allow-file: user-data — every literal here feeds a runtime WCAG contrast test on a USER-chosen
// faction colour (the candidate, the white it is tested against, and the
// fallback when it fails). All three must be strings at runtime.
/**
 * factionRing.ts — resolves the avatar ring color for a faction-tinted avatar.
 *
 * Shared by the immersive feed PostCard and the Compose-tab review-queue card
 * (#324) so the WCAG-AA fallback logic lives in exactly one place. Delegates
 * the contrast check to contrastCheck.isWcagAA (the same 3:1 non-text-contrast
 * gate MentionPill uses).
 */

import { isWcagAA } from "./contrastCheck";

/** cog-border hex in light mode — the neutral ring fallback. */
const COG_BORDER_FALLBACK = "#3D4456";

/**
 * Resolves the avatar ring color for a post/profile.
 * Uses `factionColor` when it passes WCAG AA (3:1) against white (#FFFFFF);
 * falls back to the cog-border token hex otherwise (and for an empty color).
 */
export function resolveRingColor(factionColor: string): string {
  if (!factionColor) return COG_BORDER_FALLBACK;
  return isWcagAA(factionColor, "#FFFFFF") ? factionColor : COG_BORDER_FALLBACK;
