/**
 * parseProfilesCsv.ts — client-side CSV parsing for the bulk profile import
 * dialog (Surface 6, story #292).
 *
 * The import dialog parses the chosen CSV entirely in the browser, then loops
 * `importProfiles` over the structured rows. Partial success is the NORMAL
 * outcome: a row missing a required field is reported in `issues` but is still
 * carried into `rows` so the per-row progress list can show its server result
 * (or skip it client-side — the dialog decides). Header validation, however, is
 * a hard precondition: missing required columns means we cannot map any row.
 *
 * The parser is dependency-free (no PapaParse) and handles the CSV essentials:
 * quoted fields, embedded commas, doubled-quote escaping, and CRLF/blank lines.
 *
 * Column mapping (CSV header -> ImportProfileRow field):
 *   display_name  -> display_name   (required)
 *   handle        -> username       (required)
 *   bio           -> bio
 *   location      -> location
 *   faction       -> faction_name
 *   account_type  -> account_type   (normalized, see below)
 *   verified      -> (currently informational; not on ImportProfileRow)
 *   avatar_color  -> (currently informational; not on ImportProfileRow)
 *   tags          -> tags_csv       (optional, extension column)
 *   following     -> following_csv  (optional, extension column)
 *
 * account_type vocabulary (#2192): the only current values are "synthetic"
 * and "human". A CSV cell is normalized on import (see
 * `normalizeCsvAccountType` below) rather than passed through raw, so a
 * spreadsheet exported before the #2192 vocabulary retirement — or
 * hand-edited by an operator who still remembers the old values — cannot
 * reintroduce the retired "participant"/"scripted" literals into the system.
 */

import { normalizeAccountType, type ImportProfileRow } from "../api/profiles";

/**
 * Canonical column set shown in the dialog's expected-columns table and used to
 * build the downloadable template. Order is the template's column order.
 */
export const PROFILE_CSV_HEADERS = [
  "display_name",
  "handle",
  "bio",
  "location",
  "faction",
  "account_type",
  "verified",
  "avatar_color",
] as const;

/** Columns that must be present (as headers) AND non-empty (per row). */
export const PROFILE_CSV_REQUIRED_COLUMNS = ["display_name", "handle"] as const;

export type ProfileCsvColumn = (typeof PROFILE_CSV_HEADERS)[number];

/** Why a data row was skipped (a required field was blank). */
export type ProfileCsvSkipReason =
  | "missing_display_name"
  | "missing_handle"
  | "missing_both";

/**
 * A row dropped before POST because a required field was blank. `line` is the
 * 1-BASED SOURCE CSV line number (header = line 1, first data row = line 2);
 * blank lines that are dropped during parsing are still counted so the number
 * matches what the operator sees in their file.
 */
export interface ProfileCsvSkippedRow {
  readonly line: number;
  readonly reason: ProfileCsvSkipReason;
}

export type ParseProfilesCsvResult =
  | {
      readonly ok: false;
      /** Required header names that were not found in the file. */
      readonly missingColumns: readonly string[];
      readonly rows: readonly ImportProfileRow[];
      readonly skipped: readonly ProfileCsvSkippedRow[];
    }
  | {
      readonly ok: true;
      /** Only the rows with all required fields present — what gets POSTed. */
      readonly rows: readonly ImportProfileRow[];
      /** Blank-required rows that were NOT carried into `rows`. */
      readonly skipped: readonly ProfileCsvSkippedRow[];
    };

/**
 * Tokenize a single CSV line into fields, honoring double-quoted fields with
 * embedded commas and doubled-quote ("") escaping.
 */
function splitCsvLine(line: string): string[] {
  const fields: string[] = [];
  let current = "";
  let inQuotes = false;
  for (let i = 0; i < line.length; i += 1) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"') {
        if (line[i + 1] === '"') {
          current += '"';
          i += 1;
        } else {
          inQuotes = false;
        }
      } else {
        current += ch;
      }
    } else if (ch === '"') {
      inQuotes = true;
    } else if (ch === ",") {
      fields.push(current);
      current = "";
    } else {
      current += ch;
    }
  }
  fields.push(current);
  return fields;
}

function normalizeHeader(raw: string): string {
  return raw.trim().toLowerCase();
}

/**
 * Normalize a raw `account_type` CSV cell to the current vocabulary (#2192):
 * "synthetic" | "human". This is the write-path fix for the ticket — without
 * it, a CSV containing a retired literal ("participant"/"scripted") would
 * reach the backend untouched, since neither the Go BFF nor range-svc
 * validates this field server-side (verified: no CHECK constraint, no proto
 * enum, no allowlist).
 *
 * Delegates the actual value mapping (case-insensitive match, participant ->
 * human, scripted -> synthetic) to the shared `normalizeAccountType` in
 * `api/profiles.ts` — the same helper used by `ProfileEditModal` and
 * `FactionMembersTab`. This wrapper adds two CSV-boundary-specific rules on
 * top of that shared mapping:
 *   - An empty cell (column absent from the header, or present but blank) is
 *     left as "" rather than defaulted to a value — `cellAt` already returns
 *     "" for both cases, and account_type is not a required column, so an
 *     absent value must not start silently defaulting to "synthetic".
 *   - A NON-empty but unrecognized cell (an operator typo like "robot") still
 *     falls back to "synthetic", the conservative write-time choice: this is
 *     the CSV *write* boundary, not the read-side display path — some
 *     concrete value must be written since nothing validates this field
 *     server-side, and `normalizeAccountType` itself now reports an
 *     unrecognized value as `undefined` (#2192 finding #6) rather than
 *     defaulting it, since that read-side change is about not rendering a
 *     false-confidence badge, not about what an import should persist.
 */
export function normalizeCsvAccountType(value: string): string {
  if (value.trim() === "") return value; // absent column stays absent
  return normalizeAccountType(value) ?? "synthetic";
