  if (value.trim() === "") return value; // absent column stays absent
  return normalizeAccountType(value) ?? "synthetic";
}

/**
 * Parse raw CSV text into typed import rows plus a validation report.
 */
export function parseProfilesCsv(text: string): ParseProfilesCsvResult {
  // Split WITHOUT dropping blank lines, so each surviving line keeps its
  // 1-based source line number — blank lines are skipped during parsing but
  // still advance the counter (matching the operator's file).
  const rawLines = text.split(/\r\n|\r|\n/);
  const sourceLines: ReadonlyArray<{ readonly line: number; readonly text: string }> =
    rawLines
      .map((t, i) => ({ line: i + 1, text: t }))
      .filter((entry) => entry.text.trim().length > 0);

  if (sourceLines.length === 0) {
    return {
      ok: false,
      missingColumns: [...PROFILE_CSV_REQUIRED_COLUMNS],
      rows: [],
      skipped: [],
    };
  }

  const headerCells = splitCsvLine(sourceLines[0].text).map(normalizeHeader);
  const headerIndex = new Map<string, number>();
  headerCells.forEach((name, idx) => {
    if (!headerIndex.has(name)) headerIndex.set(name, idx);
  });

  const missingColumns = PROFILE_CSV_REQUIRED_COLUMNS.filter(
    (col) => !headerIndex.has(col),
  );
  if (missingColumns.length > 0) {
    return { ok: false, missingColumns, rows: [], skipped: [] };
  }

  const cellAt = (cells: readonly string[], col: string): string => {
    const idx = headerIndex.get(col);
    if (idx === undefined) return "";
    return (cells[idx] ?? "").trim();
  };

  const rows: ImportProfileRow[] = [];
  const skipped: ProfileCsvSkippedRow[] = [];

  for (let r = 1; r < sourceLines.length; r += 1) {
    const { line, text: lineText } = sourceLines[r];
    const cells = splitCsvLine(lineText);
    const row: ImportProfileRow = {
      display_name: cellAt(cells, "display_name"),
      username: cellAt(cells, "handle"),
      bio: cellAt(cells, "bio"),
      faction_name: cellAt(cells, "faction"),
      location: cellAt(cells, "location"),
      account_type: normalizeCsvAccountType(cellAt(cells, "account_type")),
      tags_csv: cellAt(cells, "tags"),
      following_csv: cellAt(cells, "following"),
    };

    const missingName = row.display_name.length === 0;
    const missingHandle = row.username.length === 0;
    if (missingName || missingHandle) {
      const reason: ProfileCsvSkipReason =
        missingName && missingHandle
          ? "missing_both"
          : missingHandle
            ? "missing_handle"
            : "missing_display_name";
      skipped.push({ line, reason });
      continue;
    }

    rows.push(row);
  }

  return { ok: true, rows, skipped };
}

/** A single representative example row for the downloadable template. */
const TEMPLATE_EXAMPLE_ROW: Readonly<Record<ProfileCsvColumn, string>> = {
  display_name: "Ada Lovelace",
  handle: "ada_lovelace",
  bio: "Analyst tracking signals chatter.",
  location: "London",
  faction: "Red Cell",
  account_type: "synthetic",
  verified: "true",
  // design-ratchet-allow: user-data — default avatar colour written to the profile record. A user's identity colour is
  // DATA, not styling: it is persisted and rendered as an inline style on
  // user content, so it must be a literal string with no cog-* class to carry it.
  avatar_color: "#2563eb",
};

/** Quote a CSV cell if it contains a comma, quote, or newline. */
function csvQuote(value: string): string {
  if (/[",\r\n]/.test(value)) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}

/**
 * Build the downloadable CSV template: the canonical header row plus one
 * example data row. Used to populate a `data:` blob for the template link.
 */
export function buildProfilesCsvTemplate(): string {
  const header = PROFILE_CSV_HEADERS.join(",");
  const example = PROFILE_CSV_HEADERS.map((col) =>
    csvQuote(TEMPLATE_EXAMPLE_ROW[col]),
  ).join(",");
  return `${header}\n${example}\n`;
}



